#include "archpulse/thread_pool.hpp"
namespace archpulse { ThreadPool::ThreadPool(std::size_t n){if(n==0)throw std::invalid_argument("thread_count must be at least 1");workers_.reserve(n);for(std::size_t i=0;i<n;++i)workers_.emplace_back([this](){for(;;){std::function<void()> task;{std::unique_lock<std::mutex> lock(mutex_);condition_.wait(lock,[this](){return stopping_||!tasks_.empty();});if(stopping_&&tasks_.empty())return;task=std::move(tasks_.front());tasks_.pop();}task();}});} ThreadPool::~ThreadPool(){{std::lock_guard<std::mutex> lock(mutex_);stopping_=true;}condition_.notify_all();for(auto&w:workers_)if(w.joinable())w.join();} }
